import { useContext, useState } from 'react';
import AuthContext from '../context/AuthContext';

function Login() {
  const { login } = useContext(AuthContext);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);

  const submit = async (e) => {
    e.preventDefault();
    try {
      await login(email, password);
      window.location.href = '/';
    } catch (err) {
      console.error('Login error', err);
      if (err?.message === 'Network Error') {
        setError('Network Error: cannot reach backend. Is the backend running? Check browser console and backend logs.');
      } else {
        const msg = err?.response?.data?.error || err?.message || 'Login failed';
        setError(msg);
      }
    }
  };

  const [connection, setConnection] = useState(null);

  async function checkBackend() {
    try {
      const res = await fetch('http://localhost:5001/');
      const text = await res.text();
      setConnection({ ok: true, text });
    } catch (err) {
      setConnection({ ok: false, message: err.message });
    }
  }

  return (
    <div className="auth-page">
      <div className="auth-card">
        <h3>Login</h3>
        <form onSubmit={submit} className="auth-form">
          <label>Email</label>
          <input placeholder="Email" value={email} onChange={(e)=>setEmail(e.target.value)} />

          <label>Password</label>
          <input placeholder="Password" type="password" value={password} onChange={(e)=>setPassword(e.target.value)} />

          <button type="submit" className="btn btn-primary">Login</button>
          {error && <div className="error">{error}</div>}

          <div style={{ marginTop: 12 }}>
            <button type="button" className="btn btn-minor" onClick={checkBackend}>Check backend</button>
            {connection && (
              <div style={{ marginTop: 8 }}>
                {connection.ok ? <small className="muted">Backend: {connection.text}</small> : <small className="error">Connection error: {connection.message}</small>}
              </div>
            )}
          </div>
        </form>
      </div>
    </div>
  );
}

export default Login;
